// Single runnable file with multiple top-level package-private classes.
package com.bank.saga;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SagaDemo {
    private static final Logger log = Logger.getLogger(SagaDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PaymentService payments = new PaymentService();
        RewardsService rewards = new RewardsService();
        CardService cards = new CardService();

        AccountOpeningSaga saga = new AccountOpeningSaga(payments, rewards, cards);

        log.info("=== SUCCESS saga: Rajesh (card printer OK) ===");
        cards.setPrinterWorking(true);
        saga.open("SAGA-1", "SAV2001", new BigDecimal("2000"));

        log.info("=== FAILURE saga: Priya (card printer DOWN) ===");
        cards.setPrinterWorking(false);
        saga.open("SAGA-2", "CUR3001", new BigDecimal("2000"));
    }
}

// ─── Would be in service/PaymentService.java ───
class PaymentService {
    private static final Logger log = Logger.getLogger(PaymentService.class.getName());
    private final Set<String> refunded = new HashSet<>(); // idempotency guard

    void debitFee(String sagaId, String acct, BigDecimal fee) {
        log.info(() -> "[Payments] LOCAL TXN: debit fee Rs." + fee + " from " + acct);
    }

    // Compensation — idempotent: refunding twice has no extra effect.
    void refundFee(String sagaId, String acct, BigDecimal fee) {
        if (!refunded.add(sagaId)) {
            log.warning(() -> "[Payments] refund for " + sagaId + " already applied — skipping (idempotent)");
            return;
        }
        log.warning(() -> "[Payments] COMPENSATION: refund Rs." + fee + " to " + acct);
    }
}

// ─── Would be in service/RewardsService.java ───
class RewardsService {
    private static final Logger log = Logger.getLogger(RewardsService.class.getName());
    private final Set<String> reversed = new HashSet<>();

    void creditPoints(String sagaId, String acct, int points) {
        log.info(() -> "[Rewards] LOCAL TXN: credit " + points + " points to " + acct);
    }

    void reversePoints(String sagaId, String acct, int points) {
        if (!reversed.add(sagaId)) {
            log.warning(() -> "[Rewards] reversal for " + sagaId + " already applied — skipping (idempotent)");
            return;
        }
        log.warning(() -> "[Rewards] COMPENSATION: remove " + points + " points from " + acct);
    }
}

// ─── Would be in service/CardService.java ───
class CardService {
    private static final Logger log = Logger.getLogger(CardService.class.getName());
    private boolean printerWorking = true;
    void setPrinterWorking(boolean w) { this.printerWorking = w; }

    void issueCard(String sagaId, String acct) {
        if (!printerWorking) throw new RuntimeException("Card printer down");
        log.info(() -> "[Cards] LOCAL TXN: issue debit card for " + acct);
    }
}

// ─── Would be in orchestrator/AccountOpeningSaga.java ───
class AccountOpeningSaga {
    private static final Logger log = Logger.getLogger(AccountOpeningSaga.class.getName());
    private final PaymentService payments;
    private final RewardsService rewards;
    private final CardService cards;

    AccountOpeningSaga(PaymentService p, RewardsService r, CardService c) {
        this.payments = p; this.rewards = r; this.cards = c;
    }

    void open(String sagaId, String acct, BigDecimal fee) {
        Deque<Runnable> compensations = new ArrayDeque<>(); // reverse-order undo
        int points = 500;
        try {
            payments.debitFee(sagaId, acct, fee);
            compensations.push(() -> payments.refundFee(sagaId, acct, fee));

            rewards.creditPoints(sagaId, acct, points);
            compensations.push(() -> rewards.reversePoints(sagaId, acct, points));

            cards.issueCard(sagaId, acct); // may throw — irreversible step kept LAST
            log.info(() -> "[Saga " + sagaId + "] COMPLETED — account fully opened for " + acct);
        } catch (RuntimeException ex) {
            log.log(Level.SEVERE, "[Saga " + sagaId + "] step failed, compensating", ex);
            while (!compensations.isEmpty()) compensations.pop().run(); // undo in reverse
            log.warning(() -> "[Saga " + sagaId + "] COMPENSATED — account opening rolled back");
        }
    }
}

